import type {PlanReviewActivity} from '../../src/shared/plan-review.js';
export const request={brief:'Build a users endpoint with clear frontend integration.',requirements:['Return a JSON array of users with id and name.'],candidates:[{provider:'claude' as const,model:'sonnet'},{provider:'claude' as const,model:'haiku'}],reviewer:{provider:'claude' as const,model:'opus'}};
export const plan={requirements:[{id:'R1',approach:'Define a GET /users handler using the existing router and return stable string identifiers and names as JSON.',acceptance:'The endpoint returns status 200 and the expected array shape.'}],findings:[{file:'src/api.ts',evidence:'The existing router already registers all handlers in src/api.ts; extend the current error and response conventions.'}],design:'Reuse the application router and its existing JSON response helper. The GET /users handler reads the existing user repository and maps records to an explicit public schema of id and name. Preserve existing error handling and authentication behavior. The frontend uses a documented stable response format; no new dependencies or services are needed.',steps:[{title:'Add the users API contract',files:['src/api.ts'],details:'Add GET /users to the current router and map stored users to id and name. Keep access checks consistent with the neighboring handlers. Return the existing JSON helper response and document empty arrays.'},{title:'Verify the response contract',files:['tests/api.test.ts'],details:'Add an integration test with two fixture users and assert exact JSON field names, status and content type. Add an empty repository case and check unauthenticated behavior follows the current router policy.'}],verification:[{requirement:'R1',check:'Run the users route integration test and inspect the exact JSON response fields.',expected:'Status 200 with an array containing only the expected id and name fields.'}],risks:[{risk:'Stored identifiers may be numeric instead of strings.',mitigation:'Verify existing consumers and normalize identifiers consistently at the public response boundary.'}],assumptions:[{assumption:'The repository already provides a list-users read API.',verify:'Inspect the user repository interface before coding and adapt the implementation sequence if needed.'}],scope:{included:'One users read endpoint, its explicit JSON schema and route integration tests.',excluded:'No pagination, user writes, new authentication system or unrelated frontend redesign.'}};
export function verdict(m:PlanReviewActivity,scores=[8,6],winner:string|null='A') {
 return {id:m.id,revision:m.revision,winner,summary:'Candidate A provides the strongest requirement mapping and the clearest implementation sequence while preserving existing router conventions. Candidate B is feasible but has weaker verification coverage and less evidence for its integration assumptions.',ratings:m.candidates.map((c,i)=>({candidate:c.id,scores:{coverage:scores[i],feasibility:scores[i],detail:scores[i],verification:scores[i],simplicity:scores[i]},scoreReasons:Object.fromEntries(['coverage','feasibility','detail','verification','simplicity'].map(k=>[k,'The plan maps the users contract to concrete existing route code and acceptance tests.'])),gates:Object.fromEntries(['coverage','feasibility','detail'].map(k=>[k,{pass:!!c.plan,reason:'The submitted plan is detailed and maps its design to the frozen requirements.'}])),strengths:['The route design preserves existing conventions.'],weaknesses:['The repository assumptions still require verification.'],decision:c.id===winner?'accept':'reject',reason:c.id===winner?'This plan is accepted because it has the highest weighted eligible score and provides the best justified sequence for delivering the frozen users API requirement.':'This plan is rejected because the alternative has a higher eligible score, clearer verification evidence and a more specific implementation sequence for the same requirements.'}))};
}
